import{_ as s,o as a,c as o,a2 as n}from"./chunks/framework.BS0bAV7E.js";const m=JSON.parse('{"title":"Open Cube OS Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"root/ARCHITECTURE.md","filePath":"root/ARCHITECTURE.md"}'),t={name:"root/ARCHITECTURE.md"};function i(r,e,c,l,d,h){return a(),o("div",null,[...e[0]||(e[0]=[n(`<h1 id="open-cube-os-architecture" tabindex="-1">Open Cube OS Architecture <a class="header-anchor" href="#open-cube-os-architecture" aria-label="Permalink to &quot;Open Cube OS Architecture&quot;">​</a></h1><p>This document describes the tree as it exists in 2.1.0 - every component named below is a real file you can open. Line counts and per-directory detail live in <code>docs/data/stats.json</code> (regenerate: <code>make api-docs</code>).</p><h2 id="the-two-rings" tabindex="-1">The two rings <a class="header-anchor" href="#the-two-rings" aria-label="Permalink to &quot;The two rings&quot;">​</a></h2><p>Open Cube OS is a two-ring system:</p><ul><li><strong>L0 - provides services.</strong> The kernel plus drivers, service implementations and the WinRE-style recovery environment (the <code>oc&gt;</code> shell). L0 owns the hardware and every service body.</li><li><strong>L1 - uses services.</strong> Ring-3 user applications that reach L0 capability through the extension surface (the <code>SYS_L1SVC</code> op table and the classic syscall ABI). The default boot entry is the ring-3 <code>ush</code> shell, declared in <code>services/l1/l1_launcher.c</code> (<code>OC_L1_APP_DECL(&quot;ush&quot;, ..., dflt=1)</code>); <code>oc&gt;</code> is the fallback after ush exits or fails to start.</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                  GRUB 2.12 (hybrid BIOS + UEFI ISO)</span></span>
<span class="line"><span>                                  |  multiboot2 + kernel-as-module</span></span>
<span class="line"><span>        +-------------------------+-------------------------+</span></span>
<span class="line"><span>        |                   boot/boot.S                    |</span></span>
<span class="line"><span>        |  32-bit entry -&gt; GDT -&gt; 2 MiB identity map of    |</span></span>
<span class="line"><span>        |  the first 4 GiB -&gt; PAE+LME+PGE -&gt; long mode     |</span></span>
<span class="line"><span>        +---------------------------------------------------+</span></span>
<span class="line"><span>                                  |</span></span>
<span class="line"><span>   core/main.c (kmain: bring-up order = the boot log you see)</span></span>
<span class="line"><span>                                  |</span></span>
<span class="line"><span>   +-----------+-----------+------------+------------+</span></span>
<span class="line"><span>   |           |           |            |            |</span></span>
<span class="line"><span> arch/x86_64  core/mem    core/lib    core/       services/l1</span></span>
<span class="line"><span> IDT/GDT/TSS  PMM/VMM/    string/tar  scheduler   launcher,</span></span>
<span class="line"><span> exceptions   heap        gzip/config syscalls 54  SYS_L1SVC(110)</span></span>
<span class="line"><span> 8259 LAPIC   4 KiB       klog        ring3+ELF    + selftests</span></span>
<span class="line"><span> IRQ timers   pages       config      signals</span></span>
<span class="line"><span>                                  |</span></span>
<span class="line"><span>   +----------------+---------------+-----------------+</span></span>
<span class="line"><span>   |                |               |                 |</span></span>
<span class="line"><span> drivers/*       services/*      recovery/        tui/ chinese/</span></span>
<span class="line"><span> 16 families     17 folders      the oc&gt; shell    the v1 TUI/CJK</span></span>
<span class="line"><span> block NVME      folder == L1SVC 99 commands     command trees,</span></span>
<span class="line"><span> AHCI ATA DMA    category:       (self-tests,     still compiled</span></span>
<span class="line"><span> virtio-blk      fs net crypto   watchdog, crash  INTO the kernel,</span></span>
<span class="line"><span> USB UHCI/OHCI/  ota klog health policy, logs,    reachable from</span></span>
<span class="line"><span> EHCI/xHCI       watchdog power  chipset diag,    oc&gt;; CN console</span></span>
<span class="line"><span> MSC HID audio   time block nic   file commands,  + pinyin IME</span></span>
<span class="line"><span> serial, PCI     snd display     ssh/sshd)       (CONFIG_CHINESE)</span></span>
<span class="line"><span> PCIe ACPI      input camera</span></span>
<span class="line"><span> I2C SMBus      usb + services/l1</span></span>
<span class="line"><span> HPET/PMtimer/  itself</span></span>
<span class="line"><span> TSC/RTC</span></span>
<span class="line"><span> wireless bt SD camera UVC IR gameport parallel SCSI LSI</span></span>
<span class="line"><span>                                  |</span></span>
<span class="line"><span>                            l1apps/  (ring 3)</span></span>
<span class="line"><span>   ush - the boot shell (the only OC_L1_APP_DECL application):</span></span>
<span class="line"><span>   133 unique SVC rows -&gt; SYS_L1SVC, 19 built-ins, 4 NETCMD</span></span>
<span class="line"><span>   bridges; plus the embedded test programs (36 files: hello,</span></span>
<span class="line"><span>   fork/exec/pipe/signal/select/mmap, dlsym/PIE dynamic</span></span>
<span class="line"><span>   linking, g6/g7 chains) runnable through \`run\`.</span></span></code></pre></div><h2 id="boot-flow-what-the-serial-log-shows-in-order" tabindex="-1">Boot flow (what the serial log shows, in order) <a class="header-anchor" href="#boot-flow-what-the-serial-log-shows-in-order" aria-label="Permalink to &quot;Boot flow (what the serial log shows, in order)&quot;">​</a></h2><ol><li>GRUB loads <code>boot/opencube.elf</code> (the kernel is also attached as a multiboot2 module tagged <code>self</code> - the installer pattern, so <code>install</code>/<code>abdisk</code> can copy the <em>exact</em> running kernel onto a disk).</li><li><code>boot/boot.S</code>: 32-bit entry point, own GDT, identity-map the first 4 GiB with 2 MiB pages, PAE + LME + PGE, switch to 64-bit long mode, call <code>kmain</code>.</li><li><code>arch/x86_64/arch_multiboot2.c</code> parses the multiboot2 info (framebuffer, memory map, command line, module list, ACPI RSDP tags) - with full malformed-input hardening: per-tag minimums, NUL-termination checks, truncated-tag rejection.</li><li><code>kmain</code> brings up, in boot-log order: framebuffer console and font, IDT/GDT/TSS (256 gates, IST stacks for #DF/#MC and debug), 8259 PIC remap, PIT @ 100 Hz, PS/2 keyboard, COM1 serial RX, line editor, exceptions (with a live #DE/#UD/#PF self-test), PMM, VMM, heap, then the collected driver/service domains, VFS, network, crash recovery.</li><li>Services and drivers declare themselves in-file (<code>OC_SERVICE_DECL</code> / <code>OC_DRIVER_DECL</code> collected from linker sections - <code>core/core_registry.c</code>), init runs, and the launcher starts the default ring-3 application: the <code>ush&gt;</code> prompt. (The kernel links in two passes; <code>tools/embed_grub.py</code> embeds the GRUB boot+core images as <code>core/generated/grub_boot_data.c</code> so <code>grub-install</code>/<code>install</code> can write the exact boot images.)</li></ol><h2 id="memory-management" tabindex="-1">Memory management <a class="header-anchor" href="#memory-management" aria-label="Permalink to &quot;Memory management&quot;">​</a></h2><ul><li><strong>PMM</strong> (<code>core/mem/mem_pmm.{c,h}</code>): bitmap allocator over 4 KiB page frames from the multiboot2 memory map; reserved regions (kernel code, framebuffer, mbi) marked used at init; O(1) alloc/free.</li><li><strong>VMM</strong> (<code>core/mem/mem_vmm.{c,h}</code>): 4-level page tables; the kernel keeps the boot-time identity map of the first 4 GiB; APIs create and manipulate additional address spaces (user processes). Page protection flags map to rw/nx/user bits.</li><li><strong>Heap</strong> (<code>core/mem/mem_heap.{c,h}</code>): kmalloc/kfree/krealloc/ kzalloc, free-list with first-fit and coalescing, 16-byte aligned blocks, 16 MiB fail-fast ceiling.</li><li><strong>#PF growth</strong>: stack-growth and heap-growth page faults are real fault handling in the exception path - illegal accesses escalate to the crash path.</li></ul><h2 id="scheduling-and-time" tabindex="-1">Scheduling and time <a class="header-anchor" href="#scheduling-and-time" aria-label="Permalink to &quot;Scheduling and time&quot;">​</a></h2><ul><li><strong>Scheduler</strong> (<code>core/core_sched.{c,h}</code>): preemptive, priority + time-slice round-robin over task control blocks; context switch in <code>arch/x86_64/arch_context_switch.S</code>-family assembly with ABI-probe-verified alignment.</li><li><strong>Timer</strong> (<code>core/core_timer.{c,h}</code>): PIT at 100 Hz drives ticks, <code>g_boot_time_ms</code> and the soft-timer wheel. HPET, the ACPI PM timer and the TSC are supported as <em>additional</em> time sources (<code>drivers/time/</code>) - and as user-facing commands from both shells.</li><li><strong>Watchdog</strong> (<code>services/watchdog/core_watchdog.{c,h}</code>): monitored task slots with timeout policy (the <code>watchdog</code> command), plus true hardware watchdog bring-up where firmware offers it - Intel TCO (verified live on QEMU q35) and ACPI WDAT tables.</li></ul><h2 id="interrupts-and-exceptions" tabindex="-1">Interrupts and exceptions <a class="header-anchor" href="#interrupts-and-exceptions" aria-label="Permalink to &quot;Interrupts and exceptions&quot;">​</a></h2><p><code>arch/x86_64/arch_idt.{c,h}</code> + <code>arch_irq.c</code>: 256-entry IDT, TSS with IST1 (panic stack for #DF/#MC) and IST2 (dedicated exception-exit stack - never a context switch on IST2), 8259 remap to vectors 32-47, LAPIC handling, and a full exception frame path that feeds crash dump generation. A live 3/3 (#DE/#UD/#PF) self-test runs on every boot.</p><h2 id="ring-3-syscalls-the-l1-surface" tabindex="-1">Ring 3, syscalls, the L1 surface <a class="header-anchor" href="#ring-3-syscalls-the-l1-surface" aria-label="Permalink to &quot;Ring 3, syscalls, the L1 surface&quot;">​</a></h2><ul><li><strong>Syscall ABI</strong> (<code>core/core_syscall.h</code>): <code>rax</code>=number, <code>rdi/rsi/rdx/r10</code>=args (r8 = 5th arg for SYS_L1SVC), <code>rax</code>=result. 54 syscall numbers (verify: <code>grep -c &#39;#define SYS_&#39; core/core_syscall.h</code>).</li><li><strong>The service surface</strong> (<code>services/l1/l1svc_defs.h</code>): the numbered L1SVC op table - <strong>17 categories / 158 ops</strong>. Category number selects the <code>services/&lt;category&gt;/</code> folder, op selects the command; ush routes <code>SVC_CMDS</code> rows through <code>SYS_L1SVC(110)</code> to the owning L0 service body. Four network commands (ifconfig/netstat/ping/wget) reach their L0 bodies through the <code>SYS_NETCMD(101)</code> bridge instead.</li><li><strong>Counting calibers</strong> (2.1.0, stated exactly): command homes are <strong>251 unique names = 99 L0 (<code>oc&gt;</code>) + 133 ring-3 SVC + 19 ush built-ins</strong>. The ush <code>SVC_CMDS</code> table itself carries 142 rows - the 9 dual-homed names (rtc/hpet/pmtimer/tsc/shutdown/poweroff/ reboot/halt/sleep) are registered on both sides and stay callable from both shells. The v1.0.0 baseline is 233 commands, every one mapped in <code>INTERFACES.md</code> Part 1c.</li><li><strong>Interface history</strong> (2.1.0, per-entry in <code>INTERFACES.md</code> Part 2c/2d): of the v1 surface headers&#39; 278 callable declarations, 267 survive public, 6 register-class hooks moved into per-family <code>services/*/drv_internal.h</code> (&#39;internal since 2.0.0&#39;), and 5 init/probe entries were deleted - each rebuilt inside the collected-declaration service model (<code>*_svc_init</code> / <code>*_svc_probe_all</code>).</li><li><strong>User programs</strong> (<code>l1apps/</code>): 36 files - the ush shell itself, hello/fork/exec/pipe/signal/select/mmap tests, dynamic linking with a real in-tree loader (<code>l1apps/ld_so.c</code>, <code>dlsym</code>, PIE and relocation tests) - embedded into the ISO and runnable via <code>run</code>.</li></ul><h2 id="filesystems" tabindex="-1">Filesystems <a class="header-anchor" href="#filesystems" aria-label="Permalink to &quot;Filesystems&quot;">​</a></h2><ul><li><strong>VFS</strong> (<code>services/fs/fs_vfs.{c,h}</code>): uniform open/read/write/ seek/close/stat/mkdir/rmdir/readdir/lookup over registered fs types; the node tree crosses mount points transparently; per-fs case sensitivity; permission bits enforced; i64 seek.</li><li><strong>Filesystems</strong> (<code>services/fs/</code>): FAT32 (LFN with alias + collision scan + checksum validation, dual-FAT mirror, FSINFO), exFAT (active FAT), ext4 (read/write with extent support), ramfs (sparse holes zeroed).</li><li><strong>Block service</strong> (<code>services/block/</code> + <code>drivers/block/</code>): register/read/write/flush with per-instance names, partition scanning, AHCI, ATA/ATA-DMA, NVMe, virtio-blk. Driver families self-register (<code>OC_DRIVER_DECL</code>); the service half exposes the ring-3 surface (mkfs.*, fsck, abdisk...).</li><li><strong>/etc volume</strong>: a 32 MiB FAT32 image mounted at /etc holding <code>opencube.conf</code>, SSH host keys, kernel logs - so configuration survives reboots (<code>etc.img</code> target).</li></ul><h2 id="network-stack" tabindex="-1">Network stack <a class="header-anchor" href="#network-stack" aria-label="Permalink to &quot;Network stack&quot;">​</a></h2><p><code>services/net/net_core.{c,h}</code> and friends - a self-contained stack: PCI discovery, e1000-family NIC drivers (e1000/e1000e/igb/ixgbe; rtl8139/rtl8169-family; BCM57xx), Ethernet + ARP + IPv4 + ICMP + UDP + DNS + TCP with congestion control (<code>net_tcp_cc.c</code>), a socket API for user programs, stateful firewall, <code>wget</code>/<code>dns</code>/<code>ping</code>/ <code>route</code> commands. On top of it: a TLS 1.2/1.3 client with RSA/ECDHE, X.509 chain verification (RFC 6125 hostname policy) and a real SSH client + SSH server (<code>net_sshd.c</code>, key exchange via curve25519/ed-style primitives, host keys on /etc). The DRBG seeding is RDRAND + re-mixed RDTSC (NIST SP 800-90A HMAC_DRBG).</p><h2 id="drivers" tabindex="-1">Drivers <a class="header-anchor" href="#drivers" aria-label="Permalink to &quot;Drivers&quot;">​</a></h2><p>16 families under <code>drivers/</code> - each with its own bring-up manual page under <code>docs/drivers/</code>. Highlights: UHCI/OHCI/EHCI/xHCI USB stacks with MSC (mass storage), HID, serial, audio classes; HDA/AC97/SB16/ES1370/virtio sound; i2c + SMBus; wireless (ath/brcm/iwlwifi/rtlwifi families) and bluetooth (HCI/L2CAP/RFCOMM/SDP/SPP + HID) layers; UVC cameras with MJPEG; SD/SDHCI; SCSI (LSI 53C8xx family); ACPI with a real AML namespace walker (FADT/DSDT/MCFG, S3 suspend/resume in <code>arch_acpi_s3*.S</code>); chipset time sources (HPET/PM timer/TSC/CMOS RTC).</p><h2 id="the-oc-recovery-environment" tabindex="-1">The oc&gt; recovery environment <a class="header-anchor" href="#the-oc-recovery-environment" aria-label="Permalink to &quot;The oc&gt; recovery environment&quot;">​</a></h2><p><code>recovery/</code> is the WinRE-style L0 shell: tokeniser, env vars, aliases, pipes, redirection, background jobs, wildcards, command chains, cwd, script language, <code>help -a/-w</code> views, line editor with history, a text <code>editor</code> - <strong>99 commands</strong>, all registered via file-local <code>OC_SHELL_CMD</code> declarations. What deliberately lives here: the kernel self-tests, watchdog, crash policy controls, the kernel log readers (dmesg/logcat/logctl/crashlog/dumpinfo/ crashtest), chipset diagnostics, recovery file commands, and the interactive session commands (ssh/sshd).</p><h2 id="tui-and-the-chinese-console-l0-resident-command-trees" tabindex="-1">TUI and the Chinese console (L0-resident command trees) <a class="header-anchor" href="#tui-and-the-chinese-console-l0-resident-command-trees" aria-label="Permalink to &quot;TUI and the Chinese console (L0-resident command trees)&quot;">​</a></h2><p><code>tui/</code> (the windowing layer over the framebuffer: desktop with taskbar/launcher, menus, forms, panels, text widgets, a TUI editor, system monitor apps, plus the <code>tui/tui_ext.h</code> extension surface) and <code>chinese/</code> (16x16 bitmap font, GB console rendering, pinyin IME, CN TUI variants) are still compiled INTO the kernel (<code>KERNEL_DIRS</code> in the Makefile; <code>CONFIG_TUI</code>/<code>CONFIG_CHINESE</code> can build without them) - reachable as commands from <code>oc&gt;</code> and via the L1SVC surface from ush. System strings remain ASCII by contract.</p><h2 id="ota-and-a-b-updates" tabindex="-1">OTA and A/B updates <a class="header-anchor" href="#ota-and-a-b-updates" aria-label="Permalink to &quot;OTA and A/B updates&quot;">​</a></h2><p><code>services/ota/</code>: update manifest verification (SHA256 + signature), download, staged install onto A/B slots (<code>ota_ab.{c,h}</code>), rollback, boot-slot flags consumed by the GRUB menu (slot ISO / A / B). The <code>update</code> command chain runs the whole flow; <code>ab_partition_test</code> exercises slot management on a scratch disk.</p><h2 id="crash-recovery" tabindex="-1">Crash recovery <a class="header-anchor" href="#crash-recovery" aria-label="Permalink to &quot;Crash recovery&quot;">​</a></h2><p><code>core/core_crash.c</code> + <code>recovery/shell_cmds_crash.c</code>: panic path with register dump to serial + crashlog on the /etc volume, dump inspection via <code>dumpinfo</code>, an in-guest <code>crashtest</code>, and the WinRE-style recovery posture: if the ring-3 launcher fails, the system falls back to the <code>oc&gt;</code> shell - recovery is always one <code>exit</code> away from the default ring-3 session.</p>`,30)])])}const u=s(t,[["render",i]]);export{m as __pageData,u as default};
